insert into practice_context_blocks (id, exercise_id, label, image_url, text_content, block_type) values
  ('77ceb054-f61b-4dc3-8dff-1032827d3508', 'cc13b9c5-092c-4ebd-af17-0864016ca13f', $$laagconjunctuur in EMU-landen; tekortgrens van maximaal 3% van het bbp$$,
   $$economie-havo-2025-ii-macro-dilemmas-context1.png$$,
   $$In veel EMU-landen is sprake van een laagconjunctuur, in enkele landen zelfs van een recessie. Daarom pleiten economen in verschillende EMU- landen voor het voeren van anticyclisch begrotingsbeleid. De EMU-landen kunnen geen anticyclisch begrotingsbeleid voeren, als hun overheidstekort dan uitkomt boven de afgesproken grens van maximaal 3% van het bbp.$$, 'inline'),
  ('0fba4f35-486f-4726-a472-a39ddcc96b4e', 'cc13b9c5-092c-4ebd-af17-0864016ca13f', $$het beleid in het buitenland heeft gevolgen voor Nederland$$,
   $$economie-havo-2025-ii-macro-dilemmas-context2.png$$,
   $$Het beleid in het buitenland heeft gevolgen voor Nederland.$$, 'inline'),
  ('600623be-6688-4500-8b4b-191a977322a3', 'cc13b9c5-092c-4ebd-af17-0864016ca13f', $$invloed van anticyclisch begrotingsbeleid op het overheidssaldo$$,
   $$economie-havo-2025-ii-macro-dilemmas-context3.png$$,
   $$Als landen anticyclisch begrotingsbeleid gaan voeren, heeft dit ook invloed op het overheidssaldo. In onderstaande tabel is de invloed van anticyclisch begrotingsbeleid op het overheidssaldo weergegeven.$$, 'inline'),
  ('5fb001e0-240a-493b-9030-e6aca33c67f4', 'cc13b9c5-092c-4ebd-af17-0864016ca13f', $$tabel: verandering overheidssaldo van Nederland en EMU-landen$$,
   $$economie-havo-2025-ii-macro-dilemmas-context4.png$$,
   $$Verandering overheidssaldo van Nederland en EMU-landen
(eerste teken: Nederland; tweede teken: andere EMU-landen)
Nederland voert anticyclisch begrotingsbeleid / andere EMU-landen voeren anticyclisch begrotingsbeleid: ↓ ; ↓
Nederland voert anticyclisch begrotingsbeleid / andere EMU-landen voeren geen anticyclisch begrotingsbeleid: ↓↓ ; ↑
Nederland voert geen anticyclisch begrotingsbeleid / andere EMU-landen voeren anticyclisch begrotingsbeleid: ↑ ; ↓↓
Nederland voert geen anticyclisch begrotingsbeleid / andere EMU-landen voeren geen anticyclisch begrotingsbeleid: = ; =
Noot: een pijl omhoog betekent een verbetering van het overheidssaldo en een pijl omlaag betekent een verslechtering.$$, 'inline'),
  ('fb09b3d4-6504-4caf-ac92-993c61a36118', 'cc13b9c5-092c-4ebd-af17-0864016ca13f', $$extra uitgaven worden gefinancierd met leningen; hogere staatsschuld$$,
   $$economie-havo-2025-ii-macro-dilemmas-context5.png$$,
   $$Als overheden besluiten anticyclisch begrotingsbeleid te voeren, worden extra uitgaven veelal gefinancierd met leningen, wat leidt tot een hogere staatsschuld.$$, 'inline'),
  ('d4a8761c-461d-44c4-bb8d-11c3822bd14c', 'cc13b9c5-092c-4ebd-af17-0864016ca13f', $$afspraken binnen de EMU; econoom: zonder bezuinigen verliest Nederland het vertrouwen van financiële markten$$,
   $$economie-havo-2025-ii-macro-dilemmas-context6.png$$,
   $$Om de recessie te bestrijden, maar toch de overheidstekorten te bewaken, stellen regeringsleiders voor om afspraken te maken binnen de EMU over gezamenlijk anticyclisch begrotingsbeleid. Een econoom stelt dat de afspraken voor Nederland weinig uitmaken: “Als nu niet wordt bezuinigd, zal Nederland het vertrouwen van de financiële markten verliezen.”$$, 'inline'),
  ('f41a25b1-3a3a-4517-b27f-4af6b84369c7', '1ee00a3e-e9ec-4d34-96c7-494f3bf8f571', $$uit een krant: suikeraccijns in Mexico; verkoop daalt 6% (1,5 pond per persoon)$$,
   $$economie-havo-2025-ii-neem-accijns-met-een-korreltje-suiker-context1.png$$,
   $$Uit een krant:
De Mexicaanse overheid heeft op 1 januari 2014 een suikeraccijns ingevoerd om de negatieve externe effecten van overmatige suikerconsumptie terug te dringen. Sindsdien betalen Mexicanen een heffing in de vorm van een vast bedrag per pond1) suiker. De invoering van een suikeraccijns heeft in Mexico het gewenste effect gehad: over heel 2014 nam de verkoop van suiker met gemiddeld
6 procent af, wat neerkomt op een verminderde consumptie van 1,5 pond per persoon. Deze lagere consumptie blijkt niet evenredig te zijn verdeeld over de verschillende inkomensgroepen, want de vraag naar suiker van mensen met een laag inkomen is prijselastischer dan die van mensen met een hoog inkomen.
noot 1 een pond = 500 gram$$, 'inline'),
  ('0039f859-b9f3-46c8-b8e0-274205aeac7d', '1ee00a3e-e9ec-4d34-96c7-494f3bf8f571', $$doelstelling: consumptie minimaal 25% lager; prijs vóór accijns 4,50 peso$$,
   $$economie-havo-2025-ii-neem-accijns-met-een-korreltje-suiker-context2.png$$,
   $$De Mexicaanse overheid heeft als doelstelling de totale consumptie van suiker met minimaal 25% te beperken. Dit wil ze bereiken met de ingevoerde accijns. Stel dat in Mexico de prijs van een pond suiker vóór invoering van de accijns 4,50 peso bedraagt.$$, 'inline'),
  ('6c4d2825-1a89-40ea-bb78-f199157d53c7', '1ee00a3e-e9ec-4d34-96c7-494f3bf8f571', $$gevolgen voor consumenten- en producentensurplus (zie bron 2)$$,
   $$economie-havo-2025-ii-neem-accijns-met-een-korreltje-suiker-context3.png$$,
   $$De invoering van de suikeraccijns heeft gevolgen voor zowel het consumentensurplus als het producentensurplus op de markt van suiker (zie bron 2).$$, 'inline'),
  ('47e8e583-4976-48ea-a414-d2642de992a3', '1ee00a3e-e9ec-4d34-96c7-494f3bf8f571', $$bron 1: vraaglijn naar suiker van lage en hoge inkomens in Mexico$$,
   $$economie-havo-2025-ii-neem-accijns-met-een-korreltje-suiker-context4.png$$,
   $$Bron 1 Vraaglijn naar suiker van lage en hoge inkomens in Mexico
(twee grafieken met prijs per pond suiker tegen hoeveelheid suiker per pond, elk met een steile en een vlakke dalende vraaglijn vanaf hetzelfde punt op de prijsas)
grafiek 1: steile lijn = laag inkomen, vlakke lijn = hoog inkomen
grafiek 2: steile lijn = hoog inkomen, vlakke lijn = laag inkomen$$, 'inline'),
  ('d65d52bd-c05f-4ecd-9a83-3509b191a531', '1ee00a3e-e9ec-4d34-96c7-494f3bf8f571', $$bron 2: grafische weergave totale suikermarkt$$,
   $$economie-havo-2025-ii-neem-accijns-met-een-korreltje-suiker-context5.png$$,
   $$Bron 2 Grafische weergave totale suikermarkt
(grafiek: prijs per pond suiker (P) tegen hoeveelheid suiker (Q) in miljarden pond; vraaglijn Qv = −0,5P + 5 van A naar N; aanbod met accijns: Qa = 1,5P − 7; aanbod zonder accijns: Qa = 1,5P − 4; punten A, B, C, D, E, F, G, H, I, J, K, L, M en N)$$, 'inline'),
  ('2d9af51e-5e62-4ea4-b66d-9d6f43e0caa1', '3436399f-91f1-4319-a161-b67a9526e892', $$uit een krant: aandelenkoersen in de VS daalden sterk; zorgen over het consumentenvertrouwen$$,
   $$economie-havo-2025-ii-vraag-en-aanbod-van-aandelen-context1.png$$,
   $$Uit een krant:
Afgelopen maand daalden de aandelenkoersen in de Verenigde Staten (VS) zeer sterk. In één week zelfs gemiddeld met 8,5 procent. Deze daling wordt door een deel van de beursanalisten gezien als een ‘gezonde’ correctie. Andere analisten maken zich juist zorgen over het effect dat deze daling heeft op het consumentenvertrouwen.$$, 'inline'),
  ('47c67f60-d092-4b6f-9bde-1dec81eabd5b', '3436399f-91f1-4319-a161-b67a9526e892', $$de aandelenkoers wordt bepaald door vraag en aanbod van aandelen$$,
   $$economie-havo-2025-ii-vraag-en-aanbod-van-aandelen-context2.png$$,
   $$De aandelenkoers wordt bepaald door vraag en aanbod van aandelen op de aandelenmarkt.$$, 'inline'),
  ('bd13e9d2-f6d2-4377-a1ff-27353e3926c3', '3436399f-91f1-4319-a161-b67a9526e892', $$vanwege hoge inflatie heeft de Fed de rente aangepast$$,
   $$economie-havo-2025-ii-vraag-en-aanbod-van-aandelen-context3.png$$,
   $$Vanwege hoge inflatiecijfers in de VS heeft de Amerikaanse Centrale Bank (Fed) de rente aangepast.$$, 'inline'),
  ('8d3e144f-ccd3-4a23-87ff-ed1b0f58998c', '3436399f-91f1-4319-a161-b67a9526e892', $$de renteaanpassing heeft invloed via de conjunctuurzijde en de structuurzijde$$,
   $$economie-havo-2025-ii-vraag-en-aanbod-van-aandelen-context4.png$$,
   $$De aanpassing van de rente heeft, via de conjunctuurzijde, invloed op de hoogte van de aandelenkoersen. De aanpassing heeft ook effect gehad op de structuurzijde van de economie.$$, 'inline'),
  ('7704e1f0-15e8-4464-9e3a-bd122c3607e3', '3436399f-91f1-4319-a161-b67a9526e892', $$een belegger koopt op 31 januari aandelen ASML en ING en verkoopt ze op 1 april$$,
   $$economie-havo-2025-ii-vraag-en-aanbod-van-aandelen-context5.png$$,
   $$Aan het einde van het kwartaal zijn de aandelenkoersen weer gestegen. Een belegger koopt op 31 januari 4.000 aandelen ASML en 6.000 aandelen ING. Op 1 april verkoopt de belegger deze aandelen weer. De aandelenkoersen zijn weergegeven in onderstaande tabel.$$, 'inline'),
  ('28092aeb-0100-4e61-b1f6-9115036adb39', '3436399f-91f1-4319-a161-b67a9526e892', $$tabel: Nederlandse aandelenkoersen op de beurs in de VS$$,
   $$economie-havo-2025-ii-vraag-en-aanbod-van-aandelen-context6.png$$,
   $$Nederlandse aandelenkoersen op de beurs in de VS
aandeel | koers ($) 31 januari | koers ($) 1 april
ASML | 149,40 | 187,50
ING | 14,61 | 18,32$$, 'inline'),
  ('f62c8273-fbf8-4764-b1e2-4d3f77b1aa22', 'b4c88eb5-a0ce-4ec9-8b68-1f4c209adcde', $$verplichte basiszorgverzekering met wettelijke acceptatieplicht$$,
   $$economie-havo-2025-ii-verzekeraar-neemt-geen-risico-context1.png$$,
   $$In een land zijn mensen verplicht zich te verzekeren voor basiszorg. Zorgverzekeraars hebben een wettelijke acceptatieplicht voor de basiszorgverzekering.$$, 'inline'),
  ('3fb6017c-923b-449d-85ac-49fd22f58e78', 'b4c88eb5-a0ce-4ec9-8b68-1f4c209adcde', $$zorgverzekeraars richten hun marketing op doelgroepen zoals studenten$$,
   $$economie-havo-2025-ii-verzekeraar-neemt-geen-risico-context2.png$$,
   $$De zorgverzekeraars richten zich in hun marketing op specifieke doelgroepen zoals studenten. Met name studenten zijn vanwege hun lage leeftijd over het algemeen gezond, waardoor ze weinig zorgkosten maken. Deze marketing gericht op bepaalde doelgroepen kan echter leiden tot ongewenste situaties op de zorgverzekeringsmarkt.$$, 'inline'),
  ('ce182c5b-5e41-4f24-8de9-f525b98480ce', 'b4c88eb5-a0ce-4ec9-8b68-1f4c209adcde', $$verzekeraars A en C overwegen een campagne gericht op studenten (zie bron 2)$$,
   $$economie-havo-2025-ii-verzekeraar-neemt-geen-risico-context3.png$$,
   $$Zorgverzekeraars A en C zijn beide van plan om een campagne te voeren. Deze campagne is gericht op studenten. De kosten van de campagne zijn voor A en C gelijk vast bedrag. Een econoom maakt een pay-offmatrix (zie bron 2). In deze matrix zijn de winstveranderingen van de verzekeraars niet gelijk aan elkaar als één verzekeraar geen campagne voert en de andere verzekeraar wel. Als verzekeraar A bijvoorbeeld wel campagne voert en verzekeraar C niet, zal de winst van verzekeraar A met 10% stijgen. Als verzekeraar A geen campagne voert en verzekeraar C wel, zal de winst van verzekeraar C met 9% stijgen.$$, 'inline'),
  ('0e031844-8769-46d3-aa30-fc8dfd7bbe3c', 'b4c88eb5-a0ce-4ec9-8b68-1f4c209adcde', $$de overheid stelt een vereveningsfonds in voor verzekeraars met veel slechte risico's$$,
   $$economie-havo-2025-ii-verzekeraar-neemt-geen-risico-context4.png$$,
   $$De overheid in dit land heeft een vereveningsfonds ingesteld. Alle zorgverzekeraars storten per verzekerde een bedrag in dit fonds. Zorgverzekeraars met relatief veel slechte risico’s kunnen een beroep doen op dit fonds en kunnen zo een deel van de zorgkosten die ze maken compenseren.$$, 'inline'),
  ('9d862f68-bf5e-4f57-9563-c65de2c78cdf', 'b4c88eb5-a0ce-4ec9-8b68-1f4c209adcde', $$bron 1: marktaandeel van de zorgverzekeraars in Nederland$$,
   $$economie-havo-2025-ii-verzekeraar-neemt-geen-risico-context5.png$$,
   $$Bron 1 Marktaandeel als percentage van de totale afzet van de verschillende zorgverzekeraars in Nederland
(cirkeldiagram) A 27,8; B 22,5; C 16,2; D 14,4; overige 19,1$$, 'inline'),
  ('31edcae4-0dea-49d3-a624-6ac616efe291', 'b4c88eb5-a0ce-4ec9-8b68-1f4c209adcde', $$bron 2: pay-offmatrix procentuele winstveranderingen van zorgverzekeraars$$,
   $$economie-havo-2025-ii-verzekeraar-neemt-geen-risico-context6.png$$,
   $$Bron 2 Pay-offmatrix: procentuele winstveranderingen van zorgverzekeraars
(eerste getal: A; tweede getal: C)
A geen campagne / C geen campagne: 0% ; 0%
A geen campagne / C wel campagne: −5% ; +9%
A wel campagne / C geen campagne: +10% ; −6%
A wel campagne / C wel campagne: −1% ; −1%$$, 'inline'),
  ('6b754782-4260-41b7-8813-466695a49b16', '7e735f8c-06b5-4485-ad5c-bfd8bb368acf', $$marktsentiment; de president kondigt belastingverlagingen en investeringen in infrastructuur aan$$,
   $$economie-havo-2025-ii-economisch-beleid-context1.png$$,
   $$De stemming op markten wordt vaak aangeduid als het marktsentiment. Dit sentiment wordt onder meer beïnvloed door politieke gebeurtenissen, economische cijfers en verwachtingen. In een land kondigde de zojuist gekozen president haar nieuwe beleid aan. Zij heeft onder andere belastingverlagingen en omvangrijke investeringen in infrastructuur aangekondigd. De verwachting is dat door dit beleid het consumentenvertrouwen en het producentenvertrouwen zullen veranderen. Deze politieke aankondiging had grote invloed op het marktsentiment in het land.$$, 'inline'),
  ('a4b1ad79-dddd-4082-a741-3bfd5c54ef64', '7e735f8c-06b5-4485-ad5c-bfd8bb368acf', $$door de belastingverlaging ontstaat een overheidstekort$$,
   $$economie-havo-2025-ii-economisch-beleid-context2.png$$,
   $$Door de aangekondigde belastingverlaging ontstaat er een overheidstekort.$$, 'inline'),
  ('0309dc71-1fc8-47c1-bb0a-8cbace1e5488', '7e735f8c-06b5-4485-ad5c-bfd8bb368acf', $$belastingverlaging: lager tarief en hogere inkomensafhankelijke heffingskorting$$,
   $$economie-havo-2025-ii-economisch-beleid-context3.png$$,
   $$De aangekondigde belastingverlaging bestaat uit twee maatregelen. De eerste maatregel is het verlagen van het belastingtarief. De tweede maatregel is het verhogen van de inkomensafhankelijke algemene heffingskorting. Beide maatregelen staan in onderstaande tabel.$$, 'inline'),
  ('06303dcd-d378-4032-9a93-3c835f3089bf', '7e735f8c-06b5-4485-ad5c-bfd8bb368acf', $$tabel: schijven, oude en nieuwe tarieven en heffingskortingen$$,
   $$economie-havo-2025-ii-economisch-beleid-context4.png$$,
   $$schijf | belastbaar inkomen | oud tarief | oude heffingskorting | nieuw tarief | nieuwe heffingskorting
1 | $ 0 - $ 44.725 | 32% | $ 1.250 | 20% | $ 2.375
2 | $ 44.726 - $ 95.375 | 38% | $ 750 | 24% | $ 1.350
3 | $ 95.376 - $ 182.100 | 42% | $ 500 | 32% | $ 750
4 | $ 182.101 en hoger | 48% | $ 0 | 35% | $ 0$$, 'inline'),
  ('b02bea71-8b04-4bcb-8e73-c1827c915133', '7e735f8c-06b5-4485-ad5c-bfd8bb368acf', $$het gemiddelde belastingtarief bij een belastbaar inkomen van $ 40.000 verandert$$,
   $$economie-havo-2025-ii-economisch-beleid-context5.png$$,
   $$Door de aanpassing verandert het gemiddelde belastingtarief van iemand met een belastbaar inkomen van $ 40.000.$$, 'inline');

insert into practice_questions (id, exercise_id, question_number, topics, keywords, question_summary, question_image_url, question_text, context_block_ids) values
  ('46d644fb-5a22-435c-821e-0ef464611dca', 'cc13b9c5-092c-4ebd-af17-0864016ca13f', 1,
   '[{"domain": "Goede tijden, slechte tijden", "subdomain": "Overheid, centrale bank en conjunctuur"}]'::jsonb,
   '["tekortnorm", "procyclisch beleid", "recessie", "bezuinigen", "overheidstekort"]'::jsonb,
   $$Uitleggen dat een tekortnorm tijdens een recessie tot procyclisch beleid dwingt.$$,
   $$economie-havo-2025-ii-macro-dilemmas-vraag1.png$$, $$2p 1 Leg uit dat regeringen door de afgesproken grens voor het overheidstekort, tijdens een recessie, beleid moeten voeren dat de recessie juist groter maakt.$$, array['77ceb054-f61b-4dc3-8dff-1032827d3508']::uuid[]),
  ('5017c8aa-a817-4963-a590-11e80c5fbbcf', 'cc13b9c5-092c-4ebd-af17-0864016ca13f', 2,
   '[{"domain": "Goede tijden, slechte tijden", "subdomain": "Overheid, centrale bank en conjunctuur"}, {"domain": "Goede tijden, slechte tijden", "subdomain": "Conjunctuur en conjuncturele verschijnselen"}]'::jsonb,
   '["anticyclisch begrotingsbeleid", "export", "buitenlandse bestedingen", "bbp"]'::jsonb,
   $$Uitleggen hoe anticyclisch beleid in het buitenland via de export het binnenlandse bbp verhoogt.$$,
   $$economie-havo-2025-ii-macro-dilemmas-vraag2.png$$, $$2p 2 Leg uit als andere EMU-landen in een recessie anticyclisch begrotingsbeleid voeren, het bbp in Nederland kan stijgen.$$, array['0fba4f35-486f-4726-a472-a39ddcc96b4e']::uuid[]),
  ('feea9e0b-743a-455e-b8f4-a395b8f0b5fe', 'cc13b9c5-092c-4ebd-af17-0864016ca13f', 3,
   '[{"domain": "Goede tijden, slechte tijden", "subdomain": "Overheid, centrale bank en conjunctuur"}, {"domain": "Ruilen over de tijd", "subdomain": "De overheid ruilt over de tijd"}]'::jsonb,
   '["overheidssaldo", "meeliften", "belastingontvangsten", "anticyclisch begrotingsbeleid", "automatische stabilisatoren"]'::jsonb,
   $$Uitleggen hoe het overheidssaldo verandert als alleen het buitenland anticyclisch beleid voert.$$,
   $$economie-havo-2025-ii-macro-dilemmas-vraag3.png$$, $$3p 3 Verklaar de uitkomst in de cel linksonder. Doe het als volgt:
− Leg uit waarom het overheidssaldo van Nederland stijgt.
− Leg uit waarom het overheidssaldo van andere EMU-landen sterker daalt.$$, array['600623be-6688-4500-8b4b-191a977322a3', '5fb001e0-240a-493b-9030-e6aca33c67f4']::uuid[]),
  ('bcf16cfe-8e53-4445-ab4e-a13965bf7fce', 'cc13b9c5-092c-4ebd-af17-0864016ca13f', 4,
   '[{"domain": "Ruilen over de tijd", "subdomain": "De overheid ruilt over de tijd"}]'::jsonb,
   '["staatsschuld", "rentelasten", "lenen", "toekomstige overheidsbestedingen"]'::jsonb,
   $$Uitleggen hoe lenen voor anticyclisch beleid de toekomstige overheidsbestedingen beperkt.$$,
   $$economie-havo-2025-ii-macro-dilemmas-vraag4.png$$, $$2p 4 Zullen de overheidsbestedingen in de toekomst door het huidige anticyclisch begrotingsbeleid toenemen of afnemen? Leg je keuze uit.$$, array['fb09b3d4-6504-4caf-ac92-993c61a36118']::uuid[]),
  ('6ebf3d38-b0b7-4f11-9dc6-a682a02a9860', 'cc13b9c5-092c-4ebd-af17-0864016ca13f', 5,
   '[{"domain": "Ruilen over de tijd", "subdomain": "De overheid ruilt over de tijd"}, {"domain": "Risico en informatie", "subdomain": "Risico en rente"}]'::jsonb,
   '["staatsobligaties", "obligatiekoers", "kredietrisico", "rente", "staatsschuldquote"]'::jsonb,
   $$Het verband tussen overheidstekort, obligatiekoersen, kredietrisico en rente beredeneren.$$,
